        }
      });
    } else {
      Log.e(Helper.TAG, outbox.name + " executor is shutdown");
    }
  } catch (RejectedExecutionException ex) {
    Log.e(Helper.TAG, outbox.name + " submit failed: " + ex + "\n" + Log.getStackTraceString(ex));
